<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount,watch} from 'vue';
import {invoke} from '@tauri-apps/api/core';
import {messages,type Key} from './i18n';import type {AgentStatus,Request,Response,TunnelPeer,ProfileSummary} from './types';
const pages=['overview','devices','topology','diagnostics','settings'] as const;
const icons=['M3 3h8v8H3zM13 3h8v8h-8zM3 13h8v8H3zM13 13h8v8h-8z','M3 4h18v13H3zM8 21h8M12 17v4','M12 4v6m0 0L5 16m7-6 7 6M9 2h6v6H9zM2 15h6v6H2zM16 15h6v6h-6z','M3 12h4l3-8 4 16 3-8h4','M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2m0-14-2 2M7 17l-2 2'];
const page=ref<(typeof pages)[number]>('overview'),language=ref(localStorage.getItem('nex.language')||'system'),theme=ref(localStorage.getItem('nex.theme')||'system');
const lang=computed(()=>language.value==='zh'||(language.value==='system'&&navigator.language.startsWith('zh'))?'zh':'en');
const t=(k:Key)=>messages[lang.value][k];watch(language,v=>{localStorage.setItem('nex.language',v);document.documentElement.lang=lang.value},{immediate:true});watch(theme,v=>{localStorage.setItem('nex.theme',v);document.documentElement.dataset.theme=v},{immediate:true});
const slot=ref(0),profiles=ref<ProfileSummary[]>([]);
const status=ref<AgentStatus|null>(null),available=ref(false),busy=ref(false),polling=ref(false),err=ref(''),notice=ref(''),forgetConfirm=ref(false),advanced=ref(false);
const form=ref({server:'',name:'',invite:'',ca_pem:''}),search=ref(''),filter=ref('all'),sortKey=ref('name'),ascending=ref(true);
const rows=computed(()=>{const live=new Map((status.value?.tunnel?.peers||[]).map(p=>[p.ip,p]));return (status.value?.managed?.peers||[]).map(p=>({...p,live:live.get(p.ip)}))});
const mode=(p?:TunnelPeer):Key=>!p?'unknown':p.mode==='ice-selected'?'direct':p.mode==='relay-fallback'?'relay':p.mode.includes('configured')?'configured':'unknown';
const displayed=computed(()=>rows.value.filter(p=>(!search.value||[p.name,p.ip,p.dns_label||"",...(p.subnets||[])].some(v=>v.toLowerCase().includes(search.value.toLowerCase())))&&(filter.value==='all'||mode(p.live)===filter.value)).sort((a,b)=>{const key=(p:typeof a)=>sortKey.value==='ip'?p.ip:sortKey.value==='mode'?mode(p.live):p.name;return key(a).localeCompare(key(b),undefined,{numeric:true})*(ascending.value?1:-1)}));
const direct=computed(()=>rows.value.filter(p=>mode(p.live)==='direct').length),relay=computed(()=>rows.value.filter(p=>mode(p.live)==='relay').length);
const state=computed<Key>(()=>{if(!available.value)return 'unavailable';const s=status.value;if(!s?.profile)return 'stopped';if(s.tunnel)return 'running';const map:Record<string,Key>={pending:'pending',approved:'approved',revoked:'revoked',applying:'applying','authorization-expired':'expired','authorization-denied':'denied','management-unreachable':'offline','config-error':'error','tunnel-error':'error',stopped:'stopped'};return map[s.managed?.state||'']||'stopped'});
const samples=ref<{rx:number;tx:number}[]>([]),rate=ref<{rx:number;tx:number}|null>(null);let previous:{time:number;rx:bigint;tx:bigint}|null=null;let timer:number|undefined;
function sample(s:AgentStatus){if(!s.running||!s.tunnel){previous=null;rate.value=null;samples.value=[];return}try{let rx=0n,tx=0n;for(const p of s.tunnel.peers||[]){rx+=BigInt(p.rx_bytes||'0');tx+=BigInt(p.tx_bytes||'0')}const time=Date.parse(s.tunnel.updated_at);if(previous&&time>previous.time&&rx>=previous.rx&&tx>=previous.tx){const dt=(time-previous.time)/1000;rate.value={rx:Number(rx-previous.rx)/dt,tx:Number(tx-previous.tx)/dt};samples.value=[...samples.value.slice(-59),rate.value]}else if(previous&&(rx<previous.rx||tx<previous.tx)){rate.value=null;samples.value=[]}if(!previous||time>previous.time)previous={time,rx,tx}}catch{previous=null;rate.value=null;samples.value=[]}}
async function call(request:Request,quiet=false){
 if(busy.value||polling.value)return;
 const activeSlot=slot.value;
 if(quiet)polling.value=true;else{busy.value=true;err.value='';notice.value=''}
 try{
  const r=await invoke<Response>('agent_request',{request:{...request,slot:activeSlot}});
  if(slot.value!==activeSlot)return;
  available.value=true;
  if(r.status){status.value=r.status;sample(r.status)}
  if(!r.ok)throw Error(r.error||t('error'));
  const listed=await invoke<Response>('agent_request',{request:{action:'list'}});
  if(listed.ok&&listed.profiles)profiles.value=listed.profiles;
  err.value='';
  if(request.action==='enroll'){form.value.invite='';form.value.ca_pem='';notice.value=t('approveHint')}
  if(request.action==='forget')forgetConfirm.value=false;
 }catch(e){if(quiet){available.value=false;previous=null;rate.value=null;status.value=null;samples.value=[]}err.value=String(e)}
 finally{if(quiet)polling.value=false;else busy.value=false}
}
function selectProfile(n:number){
 if(busy.value||polling.value||n===slot.value)return;
 slot.value=n;status.value=null;previous=null;rate.value=null;samples.value=[];err.value='';notice.value='';forgetConfirm.value=false;
 form.value={server:'',name:'',invite:'',ca_pem:''};page.value='overview';
 void call({action:'status'});
}
const visibleProfiles=computed(()=>profiles.value.filter(p=>p.exists||p.slot===slot.value));
const emptyProfile=computed(()=>profiles.value.find(p=>!p.exists&&p.slot!==slot.value));
async function enroll(){await call({action:'enroll',server:form.value.server.trim(),name:form.value.name.trim(),invite:form.value.invite.trim(),ca_pem:form.value.ca_pem.trim()})}
function sort(k:string){if(sortKey.value===k)ascending.value=!ascending.value;else{sortKey.value=k;ascending.value=true}}
async function copy(v:string){try{await navigator.clipboard.writeText(v);notice.value=t('copied')}catch{err.value=t('error')}}
function bytes(v?:string|number){if(v===undefined||v==='')return '—';let n=Number(v),i=0;const u=['B','KiB','MiB','GiB','TiB'];if(!Number.isFinite(n)||n<0)return '—';while(n>=1024&&i<u.length-1){n/=1024;i++}return n.toFixed(i?1:0)+' '+u[i]}
function time(v?:string|number){if(!v||v==='0')return '—';const d=/^\d+$/.test(String(v))?new Date(Number(v)*1000):new Date(String(v));return isNaN(d.getTime())?'—':d.toLocaleString(lang.value==='zh'?'zh-CN':'en-US',{hour12:false})}
const max=computed(()=>Math.max(1,...samples.value.flatMap(s=>[s.rx,s.tx])));
function points(k:'rx'|'tx'){return samples.value.map((s,i)=>(i/Math.max(1,samples.value.length-1)*600)+','+(120-s[k]/max.value*110)).join(' ')}
onMounted(()=>{call({action:'status'},true);timer=window.setInterval(()=>call({action:'status'},true),2000)});onBeforeUnmount(()=>{if(timer!==undefined)clearInterval(timer)});
</script>
<template><div class="shell"><aside><div class="brand"><img src="./assets/logo.svg" alt=""/><div><strong>Network EX</strong><small>Private network</small></div></div><nav><button v-for="(p,i) in pages" :key="p" :class="{active:page===p}" @click="page=p"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"><path :d="icons[i]"/></svg>{{t(p)}}</button></nav><div class="profiles"><div class="profile-heading">{{lang==='zh'?'网络配置':'Networks'}}</div><button v-for="p in visibleProfiles" :key="p.slot" class="profile-button" :class="{selected:slot===p.slot}" :disabled="busy||polling" @click="selectProfile(p.slot)"><span class="dot" :class="{ok:p.running}"></span><span>{{p.name||p.server||(lang==='zh'?'未注册配置':'Empty profile')}}<small>p{{p.slot}} · {{p.ip||'—'}}</small></span></button><button v-if="emptyProfile" :disabled="busy||polling" @click="selectProfile(emptyProfile.slot)">+ {{lang==='zh'?'添加网络':'Add network'}}</button></div><div class="service"><span class="dot" :class="{ok:available}"></span>{{t('service')}}<small>{{available?t('ready'):t('unavailable')}}</small></div></aside>
<main><header><div><h1>{{t(page)}}</h1><span class="muted">{{status?.profile?.server||'Network EX'}}</span></div><button @click="call({action:'status'})" :disabled="busy">{{t('refresh')}}</button></header>
<div v-if="!available" class="alert"><strong>{{t('service')}} · {{t('unavailable')}}</strong><p>{{t('serviceHelp')}}</p><small>{{err}}</small></div><div v-else-if="err" class="alert danger">{{err}}</div><div v-if="notice" class="alert">{{notice}}</div>
<template v-if="page==='overview'">
<section v-if="status?.profile" class="panel"><div class="heading"><div class="power" :class="{on:!!status.tunnel}">⏻</div><div><h2>{{status.managed?.device.name||t('profile')}}</h2><span class="muted">{{t(state)}}</span></div><div class="grow"></div><button class="primary" :disabled="busy||!available||status.managed?.device.status==='revoked'" @click="call({action:status.running?'disconnect':'connect'})">{{status.running?t('disconnect'):t('connect')}}</button></div><div class="metrics"><div><small>{{t('ip')}}</small><strong>{{status.managed?.device.ip||'—'}}</strong><button v-if="status.managed?.device.ip" class="link" @click="copy(status.managed.device.ip)">{{t('copy')}}</button></div><div><small>{{t('peers')}}</small><strong>{{status.managed?.peer_count??'—'}}</strong></div><div><small>{{t('direct')}}</small><strong class="green">{{direct}}</strong></div><div><small>{{t('relay')}}</small><strong class="amber">{{relay}}</strong></div></div><p v-if="status.managed?.device.status==='pending'" class="muted">{{t('approveHint')}}</p></section>
<section v-else class="panel enroll"><h2>{{t('join')}}</h2><p class="muted">{{t('joinDesc')}}</p><p v-if="status?.profile_exists" class="alert">{{t('incomplete')}}</p><form @submit.prevent="enroll"><label>{{t('server')}}<input v-model="form.server" type="url" required placeholder="https://network.example.com"/></label><label>{{t('name')}}<input v-model="form.name" required maxlength="80"/></label><label>{{t('invite')}}<input v-model="form.invite" type="password" required minlength="43" maxlength="43" autocomplete="off"/></label><button type="button" class="link" @click="advanced=!advanced">{{t('advanced')}} {{advanced?'−':'+'}}</button><label v-if="advanced">{{t('ca')}}<textarea v-model="form.ca_pem" rows="4" maxlength="32768" placeholder="-----BEGIN CERTIFICATE-----"></textarea></label><button class="primary" :disabled="busy||!available||!!status?.profile_exists">{{busy?t('working'):t('enroll')}}</button></form></section>
<section v-if="status?.tunnel?.discovery" class="panel"><h2>{{lang==='zh'?'游戏联机发现':'LAN game discovery'}}</h2><div class="metrics"><div><small>{{lang==='zh'?'已封装':'Encapsulated'}}</small><strong>{{status.tunnel.discovery.sent}}</strong></div><div><small>{{lang==='zh'?'已解封装':'Decoded'}}</small><strong>{{status.tunnel.discovery.received}}</strong></div><div><small>{{lang==='zh'?'已丢弃':'Dropped'}}</small><strong>{{status.tunnel.discovery.dropped}}</strong></div></div><p class="muted">{{lang==='zh'?'仅转发管理员批准的 UDP 广播与多播；计数随隧道重建重置。':'Approved UDP broadcast and multicast only; counters reset when the tunnel is rebuilt.'}}</p></section><section class="panel"><h2>{{t('traffic')}}</h2><div class="rates"><span class="blue">{{t('rx')}} <strong>{{rate?bytes(rate.rx)+'/s':'—'}}</strong></span><span class="green">{{t('tx')}} <strong>{{rate?bytes(rate.tx)+'/s':'—'}}</strong></span></div><div v-if="samples.length>=2" class="chart"><svg viewBox="0 0 600 125" preserveAspectRatio="none"><path d="M0 10H600M0 65H600M0 120H600" class="gridline"/><polyline :points="points('rx')" class="rxline"/><polyline :points="points('tx')" class="txline"/></svg><div class="ticks"><span>{{bytes(max)}}/s</span><span>{{bytes(max/2)}}/s</span><span>0 B/s</span></div></div><div v-else class="empty">{{t('noData')}}</div><small class="muted">{{t('trafficHint')}}</small></section></template>
<template v-else-if="page==='devices'"><section class="panel"><div class="toolbar"><input v-model="search" :placeholder="t('search')"/><select v-model="filter"><option value="all">{{t('all')}}</option><option value="direct">{{t('direct')}}</option><option value="relay">{{t('relay')}}</option><option value="unknown">{{t('unknown')}}</option></select><span class="grow"></span><small>{{displayed.length}} / {{rows.length}}</small></div><div class="tablewrap"><table><thead><tr><th><button @click="sort('name')">{{t('name')}} {{sortKey==='name'?(ascending?'↑':'↓'):''}}</button></th><th><button @click="sort('ip')">{{t('ip')}} {{sortKey==='ip'?(ascending?'↑':'↓'):''}}</button></th><th><button @click="sort('mode')">{{t('mode')}} {{sortKey==='mode'?(ascending?'↑':'↓'):''}}</button></th><th>{{t('handshake')}}</th><th>{{t('rx')}}</th><th>{{t('tx')}}</th></tr></thead><tbody><tr v-for="p in displayed" :key="p.id"><td>{{p.name}}</td><td><button class="link" @click="copy(p.ip)">{{p.ip}}</button></td><td :class="mode(p.live)">{{t(mode(p.live))}}</td><td>{{time(p.live?.handshake_unix)}}</td><td>{{bytes(p.live?.rx_bytes)}}</td><td>{{bytes(p.live?.tx_bytes)}}</td></tr></tbody></table><div v-if="!displayed.length" class="empty">{{t('noPeers')}}</div></div><p class="muted">{{t('pathHint')}}</p></section></template>
<template v-else-if="page==='topology'"><section class="panel"><div class="topology"><div class="node self"><strong>{{status?.managed?.device.name||t('local')}}</strong><span>{{status?.managed?.device.ip||'—'}}</span></div><div class="nodes"><div v-for="p in rows" :key="p.id" class="branch"><div class="edge" :class="mode(p.live)"></div><div class="node"><strong>{{p.name}}</strong><span>{{p.ip}}</span><small v-if="p.dns_label">{{p.dns_label}}.p{{slot}}.network-ex.internal</small><small v-if="p.subnets?.length">{{p.subnets.join(", ")}}</small><span :class="mode(p.live)">{{t(mode(p.live))}}</span></div></div><div v-if="!rows.length" class="empty">{{t('noPeers')}}</div></div></div><p class="muted">{{t('pathHint')}}</p></section></template>
<template v-else-if="page==='diagnostics'"><section class="panel"><dl><dt>{{t('platform')}}</dt><dd>{{status?.platform||'—'}}</dd><dt>{{t('version')}}</dt><dd>{{status?.version||'—'}}</dd><dt>{{t('revision')}}</dt><dd>{{status?.managed?.revision??'—'}}</dd><dt>{{t('expires')}}</dt><dd>{{time(status?.managed?.valid_until)}}</dd><dt>{{t('updated')}}</dt><dd>{{time(status?.managed?.updated_at)}}</dd><dt>{{t('reason')}}</dt><dd>{{status?.error||status?.managed?.error||'—'}}</dd></dl><button @click="copy(JSON.stringify(status,null,2))" :disabled="!status">{{t('copy')}}</button></section><section class="panel"><pre>{{JSON.stringify(status,null,2)}}</pre></section></template>
<template v-else><section class="panel"><h2>{{t('settings')}}</h2><div class="setting">{{t('language')}}<select v-model="language"><option value="system">{{t('system')}}</option><option value="zh">简体中文</option><option value="en">English</option></select></div><div class="setting">{{t('theme')}}<select v-model="theme"><option value="system">{{t('system')}}</option><option value="light">{{t('light')}}</option><option value="gray">{{t('gray')}}</option><option value="dark">{{t('dark')}}</option></select></div></section><section class="panel"><h2>{{t('profile')}}</h2><dl><dt>{{t('server')}}</dt><dd>{{status?.profile?.server||'—'}}</dd><dt>{{t('identity')}}</dt><dd>{{status?.profile?.id||'—'}}</dd><dt>{{t('network')}}</dt><dd>{{status?.profile?.network_id||'—'}}</dd><dt>{{t('startup')}}</dt><dd>{{status?.desired?t('yes'):t('no')}}</dd></dl><p class="muted">{{t('privateKey')}}</p><p class="muted">{{t('closeHint')}}</p><button class="danger" :disabled="busy||!available||!status?.profile_exists||status.running" @click="forgetConfirm=true">{{t('forget')}}</button><div v-if="forgetConfirm" class="alert"><p>{{t('forgetConfirm')}}</p><button class="danger" @click="call({action:'forget',confirm:true})">{{t('confirm')}}</button> <button @click="forgetConfirm=false">{{t('cancel')}}</button></div></section></template>
</main><footer><span><span class="dot" :class="{ok:available}"></span> {{t('service')}} · {{available?t('ready'):t('unavailable')}}</span><span>{{status?.version||'0.7.0-dev-m7'}}</span></footer></div></template>